import{_ as a,o as s,c as e,a2 as i}from"./chunks/framework.Bqa2y7hU.js";const u=JSON.parse('{"title":"云编译与上架","description":"用云编译服务把源码变成插件包（上传源码 → 审查 → 编译 → 下载产物），以及上架到插件市场与安装到机器人。","frontmatter":{"title":"云编译与上架","description":"用云编译服务把源码变成插件包（上传源码 → 审查 → 编译 → 下载产物），以及上架到插件市场与安装到机器人。"},"headers":[],"relativePath":"plugin-dev/publish.md","filePath":"plugin-dev/publish.md","lastUpdated":1789792423000}'),n={name:"plugin-dev/publish.md"};function d(o,t,p,l,r,c){return s(),e("div",null,[...t[0]||(t[0]=[i(`<h1 id="云编译与上架" tabindex="-1">云编译与上架 <a class="header-anchor" href="#云编译与上架" aria-label="Permalink to &quot;云编译与上架&quot;">​</a></h1><p>写完了插件，还差两步：<strong>把它编译出来</strong>、<strong>让它出现在插件市场</strong>。这页给两条路：</p><ul><li><strong>云编译服务</strong>（推荐给没有 Linux 编译环境的作者）：上传源码 zip，服务端帮你编译并打包；</li><li><strong>本地自己编译</strong>：本地有 g++ 时更快，编完直接上传动态库。</li></ul><h2 id="云编译服务是什么" tabindex="-1">云编译服务是什么 <a class="header-anchor" href="#云编译服务是什么" aria-label="Permalink to &quot;云编译服务是什么&quot;">​</a></h2><p>一个网页工具：<strong>上传源码 zip → 网页审查 → 点编译 → 看实时日志 → 下载插件包</strong>。</p><p>它的职责边界很清楚：<strong>只编译，不运行你的插件业务逻辑</strong>。产物是与你自建服务器同架构的动态库，拿回来就能上传到控制台。</p><div class="tip custom-block"><p class="custom-block-title">为什么需要它</p><p>云编译在 Ubuntu 24.04 x86_64 上编译——与框架服务器一致。你在 Windows 上写的插件，用本地编译器产出的动态库不能直接在服务器上加载，云编译正好解决这个问题。</p></div><h2 id="_1-准备源码" tabindex="-1">1. 准备源码 <a class="header-anchor" href="#_1-准备源码" aria-label="Permalink to &quot;1. 准备源码&quot;">​</a></h2><p>源码要求（不满足会在审查阶段被拦下）：</p><table tabindex="0"><thead><tr><th>要求</th><th>说明</th></tr></thead><tbody><tr><td>语言</td><td>纯 C / C++</td></tr><tr><td>头文件</td><td>只依赖 SDK：<code>#include &quot;plugin_sdk.hpp&quot;</code>（header-only，无外部依赖）</td></tr><tr><td>扩展名</td><td><code>.c</code> / <code>.cc</code> / <code>.cpp</code> / <code>.cxx</code></td></tr><tr><td>多文件</td><td>允许；所有源文件会被<strong>一起编进同一个</strong> <code>plugin.so</code></td></tr><tr><td>第三方库</td><td><strong>v1 不支持</strong>，请保持自包含</td></tr><tr><td>注册</td><td>用 <code>BOT_REGISTER_PLUGIN(&quot;code&quot;,&quot;名称&quot;,&quot;版本&quot;,&quot;作者&quot;,&quot;分类&quot;)</code> 注册，回调按需实现</td></tr></tbody></table><p>最小可用的源码就是 <a href="/RuaBot.Doc/plugin-dev/minimal">最小示例</a> 里那份 <code>echo.cpp</code>，直接拿它试跑一遍最快。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>myplugin.zip</span></span>
<span class="line"><span>└── mybot.cpp          # 只放源码；SDK 由云编译服务提供</span></span></code></pre></div><h2 id="_2-上传源码-zip" tabindex="-1">2. 上传源码 zip <a class="header-anchor" href="#_2-上传源码-zip" aria-label="Permalink to &quot;2. 上传源码 zip&quot;">​</a></h2><p>打开云编译服务的网页，把源码 zip 拖进去。服务端的限制：</p><table tabindex="0"><thead><tr><th>项</th><th>限制</th></tr></thead><tbody><tr><td>单个 zip 大小</td><td>8 MB</td></tr><tr><td>解压后总大小</td><td>50 MB</td></tr><tr><td>解压后文件数</td><td>200</td></tr><tr><td>单次编译超时</td><td>180 秒</td></tr></tbody></table><h2 id="_3-网页审查" tabindex="-1">3. 网页审查 <a class="header-anchor" href="#_3-网页审查" aria-label="Permalink to &quot;3. 网页审查&quot;">​</a></h2><p>上传后页面会列出这次要编译的源文件清单，<strong>先看一眼再点编译</strong>——这一步是给你自己确认「上传的是最新代码、没有多余文件」。审查通过后点「编译」。</p><h2 id="_4-编译与实时日志" tabindex="-1">4. 编译与实时日志 <a class="header-anchor" href="#_4-编译与实时日志" aria-label="Permalink to &quot;4. 编译与实时日志&quot;">​</a></h2><p>编译过程有<strong>实时日志</strong>（流式输出），可以边编边看。常见失败原因：</p><table tabindex="0"><thead><tr><th>日志线索</th><th>原因</th></tr></thead><tbody><tr><td><code>fatal error: plugin_sdk.hpp: No such file</code></td><td>源码里 include 路径写错，或者头文件名拼错</td></tr><tr><td><code>error: &#39;xxx&#39; was not declared</code></td><td>用了 SDK 里不存在的符号，或忘了 <code>#include &quot;plugin_sdk.hpp&quot;</code></td></tr><tr><td><code>error: … C++17</code> 相关</td><td>代码用到更高或更低标准的特性，调整语法</td></tr><tr><td>超时</td><td>源文件过多或模板展开过大，精简代码</td></tr></tbody></table><h2 id="_5-下载产物" tabindex="-1">5. 下载产物 <a class="header-anchor" href="#_5-下载产物" aria-label="Permalink to &quot;5. 下载产物&quot;">​</a></h2><p>编译成功后下载得到 <code>plugin.zip</code>，里面是两样东西：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>plugin.zip</span></span>
<span class="line"><span>├── plugin.so        # 编译好的插件（C ABI，ABI 1.5）</span></span>
<span class="line"><span>└── manifest.json    # {abi, sdk_version, built_at, source_files, plugin{...}}</span></span></code></pre></div><p><code>manifest.json</code> 是给云编译服务与你自己核对信息用的；<strong>上传到控制台时它会被忽略</strong>（控制台只认 <code>.so</code>/<code>.dll</code> 与 <code>web/</code> 目录），所以带不带它都能直接上传。</p><h2 id="_6-上架与安装" tabindex="-1">6. 上架与安装 <a class="header-anchor" href="#_6-上架与安装" aria-label="Permalink to &quot;6. 上架与安装&quot;">​</a></h2><p>拿到产物后走三步：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 管理后台 → 插件上传 → 拖入 plugin.zip（或其中解出来的 .so）</span></span>
<span class="line"><span>2. 上传即热加载，插件出现在「插件市场」，对用户可见</span></span>
<span class="line"><span>3. 用户（或你）在插件市场点「安装」，选择要装到哪台机器人</span></span></code></pre></div><p>上传时控制台会自动从动态库里<strong>读取元数据</strong>（编码、名称、版本、作者、分类、logo、设置项、面板入口），不需要手填。上传后可随时在管理后台启停或隐藏这个插件。</p><p>带 Web 面板的插件要注意：<strong>打包 zip 时必须把 <code>web/</code> 目录一起打进去</strong>（云编译只编源码，不产出你的前端资源）。正确做法是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>上架用的 zip</span></span>
<span class="line"><span>├── plugin.so          # 云编译产物</span></span>
<span class="line"><span>└── web/               # 你的面板前端（自己打包进来）</span></span>
<span class="line"><span>    └── index.html</span></span></code></pre></div><h2 id="本地自己编译的路线" tabindex="-1">本地自己编译的路线 <a class="header-anchor" href="#本地自己编译的路线" aria-label="Permalink to &quot;本地自己编译的路线&quot;">​</a></h2><p>本地有 g++ 时不必绕云编译：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1) 编出动态库</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">g++</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -shared</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fPIC</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -std=c++17</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mybot.cpp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mybot.so</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -I./include</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2) 管理后台 → 插件上传 → 拖入 mybot.so（或连 web/ 一起打成 zip）</span></span></code></pre></div><p>两条路的产物完全等价，区别只有编译环境：<strong>本地编译要自己保证与服务器架构一致</strong>（服务器是 Linux x86_64）。在 Windows 上直接编出的 <code>.dll</code> 不能上传到 Linux 服务器使用，这种场景请走云编译。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="/RuaBot.Doc/plugin-dev/debugging">调试与排错</a>：编译通过但加载失败、插件不触发怎么查</li><li><a href="/RuaBot.Doc/plugin-dev/abi">ABI 与兼容规则</a>：产物声明的 ABI 版本与框架怎么协商</li><li><a href="/RuaBot.Doc/plugin-dev/structure">目录结构与打包</a>：zip 里放什么、面板怎么随包发布</li></ul>`,36)])])}const g=a(n,[["render",d]]);export{u as __pageData,g as default};
